begin read only;
select 'clock', to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS');
select 'audit', a.id, a.community_id, a.action, a.actor_type, a.actor_user_id, a.object_type, a.object_id, a.created_at from public.audit_logs a;
select 'community', c.id, c.slug, c.name, c.created_by from public.communities c where c.id in (select community_id from public.audit_logs);
select 'member', m.id, m.community_id, m.user_id, m.member_code from public.members m where m.id in (select object_id from public.audit_logs);
select 'archive', a.msg_id, a.read_ct, a.enqueued_at, a.archived_at, a.message->>'audit_log_id', a.message->>'community_id', a.message->>'action', a.message->>'object_id', a.message->>'actor_user_id' from pgmq.a_notification_events a;
select 'archive_keys', string_agg(k, ',' order by k) from pgmq.a_notification_events a cross join lateral jsonb_object_keys(a.message) k;
select 'event', e.id, e.community_id, e.event_type, e.event_key, e.actor_user_id, e.object_id, e.payload::text from public.notification_events e where e.community_id in (select community_id from public.audit_logs);
select 'delivery', d.id, d.notification_event_id, d.channel, d.status, d.error_code, d.recipient_address, d.recipient_address_assurance, d.recipient_user_id, d.dedupe_key, d.send_class, d.attempt_count, d.provider_message_id, d.send_lease_token, d.send_lease_expires_at from public.notification_deliveries d where d.community_id in (select community_id from public.audit_logs);
select 'delivery_ledger', count(*), min(attempted_at), max(attempted_at) from public.notification_send_attempts s where s.community_id in (select community_id from public.audit_logs);
select 'q_main', count(*), count(*) filter (where read_ct > 0) from pgmq.q_notification_events;
select 'a_main', count(*) from pgmq.a_notification_events;
select 'q_held', count(*) from pgmq.q_notification_events_held;
select 'a_held', count(*) from pgmq.a_notification_events_held;
select 'email_status', status::text, count(*) from public.notification_deliveries where channel='email' group by 2 order by 2;
select 'email_quarantined', count(*) from public.notification_deliveries where channel='email' and error_code='itest_quarantined';
select 'open_any', count(*) from public.notification_deliveries where status in ('pending','sending');
select 'leases', count(*) from public.notification_deliveries where send_lease_token is not null or send_lease_expires_at is not null;
select 'sender_state', count(*), bool_or(email_sending_enabled), coalesce(max(last_heartbeat_at)::text,'null'), coalesce(max(last_claim_at)::text,'null'), max(updated_at)::text from public.notification_sender_state;
select 'switch_fn', app.email_sending_enabled();
select 'mutex_held', count(*) from pg_locks where locktype='advisory' and classid=918273 and objid=1;
select 'advisory_any', count(*) from pg_locks where locktype='advisory';
select 'itest_sessions', count(*) from pg_stat_activity where usename='kolekto_itest' or application_name like 'kolekto-itest%';
select 'l4', count(*) filter (where send_class='transactional' and attempted_at > now() - interval '24 hours') from public.notification_send_attempts;
select 'ledger_total', count(*), max(attempted_at)::text, count(*) filter (where attempted_at > now() - interval '60 minutes') from public.notification_send_attempts;
select 'ledger_since_start', count(*) from public.notification_send_attempts where attempted_at >= timestamptz '2026-11-05 16:10:57+00';
select 'events', count(*) from public.notification_events;
select 'events_since_start', count(*) from public.notification_events where created_at >= timestamptz '2026-11-05 16:10:57+00';
select 'audit_count', count(*) from public.audit_logs;
select 'communities', count(*), count(*) filter (where slug like 'itest-%') from public.communities;
select 'communities_since_start', count(*) from public.communities where created_at >= timestamptz '2026-11-05 16:10:57+00';
select 'suppression_log', count(*) from public.notification_suppression_log;
select 'pgss_ext', count(*) from pg_extension where extname='pg_stat_statements';
rollback;
